public interface IRecruitmentRequisitionService { Task<IReadOnlyList<RecruitmentRequisitionRow>> ListAsync(CancellationToken ct=default); Task<IReadOnlyList<AvailablePositionMatrixOption>> ListAvailablePositionsAsync(CancellationToken ct=default); Task<ServiceResult> CreateAsync(RecruitmentRequisitionInput input,CancellationToken ct=default); Task<ServiceResult> ApproveAsync(int requisitionId,CancellationToken ct=default); Task<ServiceResult> CreateVacancyAsync(RecruitmentVacancyInput input,CancellationToken ct=default); Task<ServiceResult> PublishVacancyAsync(int vacancyId,CancellationToken ct=default); Task<RecruitmentPolicyWorkspaceDto> GetPoliciesAsync(CancellationToken ct=default); Task<ServiceResult> CreatePolicyAsync(CreateRecruitmentPolicyInput input,CancellationToken ct=default); Task<ServiceResult> VerifyApprovePolicyAsync(int versionId,CancellationToken ct=default); Task<ServiceResult> AssignPolicyAsync(AssignRecruitmentPolicyInput input,CancellationToken ct=default); Task<ServiceResult> TogglePolicyAssignmentAsync(int assignmentId,CancellationToken ct=default); }
